        +(k[85]*y[:,12]*y[:,2] - k[86]*y[:,11]*y[:,0])  # R85: C2H + H2O -> C2H2 + OH
        -(k[93]*y[:,14]*y[:,0] - k[94]*y[:,13]*y[:,2])  # R93: C2H4 + OH -> C2H3 + H2O
        -(k[99]*y[:,16]*y[:,0] - k[100]*y[:,15]*y[:,2])  # R99: C2H6 + OH -> C2H5 + H2O
        +(k[101]*y[:,5]*y[:,4] - k[102]*y[:,0]*y[:,6])  # R101: CH + O -> OH + C
        +(k[105]*y[:,4]*y[:,8] - k[106]*y[:,7]*y[:,0])  # R105: O + CH3 -> CH2 + OH
        -(k[107]*y[:,8]*y[:,0] - k[108]*y[:,4]*y[:,9])  # R107: CH3 + OH -> O + CH4
        +(k[109]*y[:,4]*y[:,16] - k[110]*y[:,0]*y[:,15])  # R109: O + C2H6 -> OH + C2H5
        -(k[111]*y[:,0]*y[:,6] - k[112]*y[:,17]*y[:,3])  # R111: OH + C -> CO + H
