        -(k[117]*y[:,0]*y[:,13] - k[118]*y[:,2]*y[:,11])  # R117: OH + C2H3 -> H2O + C2H2
        -(k[119]*y[:,0]*y[:,15] - k[120]*y[:,2]*y[:,14])  # R119: OH + C2H5 -> H2O + C2H4
        +(k[121]*y[:,19]*y[:,3] - k[122]*y[:,0]*y[:,8])  # R121: CH2OH + H -> OH + CH3
        -(k[133]*y[:,21]*y[:,0] - k[134]*y[:,17]*y[:,2])  # R133: HCO + OH -> CO + H2O
        +(k[139]*y[:,22]*y[:,4] - k[140]*y[:,20]*y[:,0])  # R139: CH3O + O -> H2CO + OH
        -(k[141]*y[:,22]*y[:,0] - k[142]*y[:,20]*y[:,2])  # R141: CH3O + OH -> H2CO + H2O
        -(k[149]*y[:,7]*y[:,0] - k[150]*y[:,20]*y[:,3])  # R149: CH2 + OH -> H2CO + H
        +(k[167]*y[:,4]*y[:,13] - k[168]*y[:,11]*y[:,0])  # R167: O + C2H3 -> C2H2 + OH
