        +(k[869]*y[:,7]*y[:,12] - k[870]*y[:,86]*y[:,3])  # R869: CH2 + C2H -> C3H2 + H
        +(k[871]*y[:,5]*y[:,11] - k[872]*y[:,86]*y[:,3])  # R871: CH + C2H2 -> C3H2 + H
        +(k[877]*y[:,6]*y[:,11] - k[878]*y[:,86])  # R877: C + C2H2 -> C3H2
        -(k[1097]*y[:,86]*y[:,3]*M - k[1098]*y[:,85]*M)  # R1097: C3H2 + H + M -> C3H3 + M
